const StatCard = ({ icon: Icon, title, value, change, color }) => {
  return (
    <div className="bg-white rounded-xl p-6 shadow-md border border-gray-100 hover:shadow-lg transition duration-200">
      <div className="flex items-center justify-between">
        <div>
          <p className="text-sm text-gray-600 mb-1">{title}</p>
          <p className="text-2xl font-bold text-gray-900">{value}</p>
          {change && (
            <p className={`text-sm ${change > 0 ? 'text-green-600' : 'text-red-600'} mt-1 flex items-center`}>
              {change > 0 ? (
                <span className="mr-1">↗</span>
              ) : (
                <span className="mr-1">↘</span>
              )}
              {Math.abs(change)}% vs mois dernier
            </p>
          )}
        </div>
        <div className={`p-3 rounded-lg ${color} shadow-md`}>
          <Icon className="h-6 w-6 text-white" />
        </div>
      </div>
    </div>
  )
}

export default StatCard
